<?php
require_once "config/db.php"; $pageTitle='Members';
if($_SERVER['REQUEST_METHOD']==='POST' && ($_POST['action']??'')==='add'){
 $name=trim($_POST['name']??'');$email=strtolower(trim($_POST['email']??''));$phone=trim($_POST['phone']??'');$gender=$_POST['gender']??'Prefer not to say';$join=$_POST['join_date']??date('Y-m-d');$plan=$_POST['plan_id']?:null;$status=$_POST['status']??'Active';
 if(strlen($name)<2||!filter_var($email,FILTER_VALIDATE_EMAIL)||!preg_match('/^[0-9]{10,15}$/',$phone)){$_SESSION['flash']=['type'=>'error','message'=>'Please enter valid member details.'];}
 else {try{$st=$pdo->prepare("INSERT INTO members(name,email,phone,gender,join_date,plan_id,status) VALUES(?,?,?,?,?,?,?)");$st->execute([$name,$email,$phone,$gender,$join,$plan,$status]);$_SESSION['flash']=['type'=>'success','message'=>'Member added successfully.'];}catch(PDOException $e){$_SESSION['flash']=['type'=>'error','message'=>'Email already registered or selected plan is invalid.'];}}
 header("Location: members.php");exit;
}
if($_SERVER['REQUEST_METHOD']==='POST' && ($_POST['action']??'')==='delete'){ $st=$pdo->prepare("DELETE FROM members WHERE id=?");$st->execute([(int)$_POST['id']]);$_SESSION['flash']=['type'=>'success','message'=>'Member deleted.'];header("Location: members.php");exit;}
$q=trim($_GET['q']??'');$status=$_GET['status']??'';$sql="SELECT m.*,p.name plan_name FROM members m LEFT JOIN plans p ON p.id=m.plan_id WHERE (m.name LIKE ? OR m.email LIKE ? OR m.phone LIKE ?)";$params=["%$q%","%$q%","%$q%"];if(in_array($status,['Active','Inactive'],true)){$sql.=" AND m.status=?";$params[]=$status;}$sql.=" ORDER BY m.id DESC";$st=$pdo->prepare($sql);$st->execute($params);$members=$st->fetchAll();$plans=$pdo->query("SELECT * FROM plans ORDER BY price")->fetchAll();
require "includes/header.php";
?><div class="page-intro"><div><h1>Member management</h1><p>Keep every membership detail organized in one place.</p></div><a class="btn btn-primary" href="#add-member">＋ Add member</a></div>
<section class="panel" id="add-member"><div class="panel-head"><div><h3>Add new member</h3><p>Fields marked with * are required.</p></div><span class="tag">NEW PROFILE</span></div><form method="post" class="form-grid" data-validate><input type="hidden" name="action" value="add"><div class="field"><label>Full name *</label><input name="name" required minlength="2" placeholder="e.g. Rohan Mehta"></div><div class="field"><label>Email address *</label><input name="email" type="email" required placeholder="name@example.com"></div><div class="field"><label>Mobile number *</label><input name="phone" pattern="[0-9]{10,15}" required placeholder="10-digit mobile number"></div><div class="field"><label>Gender</label><select name="gender"><option>Prefer not to say</option><option>Female</option><option>Male</option><option>Other</option></select></div><div class="field"><label>Join date *</label><input name="join_date" type="date" value="<?= date('Y-m-d') ?>" required></div><div class="field"><label>Membership plan</label><select name="plan_id"><option value="">Choose a plan</option><?php foreach($plans as $p): ?><option value="<?= $p['id'] ?>"><?= htmlspecialchars($p['name']) ?> — ₹<?= number_format($p['price']) ?></option><?php endforeach; ?></select></div><div class="field"><label>Status</label><select name="status"><option>Active</option><option>Inactive</option></select></div><div class="field field-action"><button class="btn btn-primary">Save member →</button></div></form></section>
<section class="panel"><div class="panel-head"><div><h3>All members <span class="count"><?= count($members) ?></span></h3><p>Search, filter and manage member profiles.</p></div></div><form class="toolbar"><input name="q" value="<?= htmlspecialchars($q) ?>" placeholder="Search name, email or phone..."><select name="status"><option value="">All statuses</option><option <?= $status==='Active'?'selected':'' ?>>Active</option><option <?= $status==='Inactive'?'selected':'' ?>>Inactive</option></select><button class="btn btn-secondary">Apply</button><a class="btn btn-plain" href="members.php">Reset</a></form><div class="table-wrap"><table><thead><tr><th>MEMBER</th><th>PHONE</th><th>PLAN</th><th>JOIN DATE</th><th>STATUS</th><th>ACTIONS</th></tr></thead><tbody><?php foreach($members as $m): ?><tr><td><div class="person"><span class="table-avatar"><?= strtoupper(substr($m['name'],0,1)) ?></span><span><b><?= htmlspecialchars($m['name']) ?></b><small><?= htmlspecialchars($m['email']) ?></small></span></div></td><td><?= htmlspecialchars($m['phone']) ?></td><td><?= htmlspecialchars($m['plan_name']??'No plan') ?></td><td><?= htmlspecialchars($m['join_date']) ?></td><td><span class="status <?= strtolower($m['status']) ?>"><?= htmlspecialchars($m['status']) ?></span></td><td class="actions"><a href="member_edit.php?id=<?= $m['id'] ?>">Edit</a><form method="post" onsubmit="return confirm('Delete this member and attendance history?')"><input type="hidden" name="action" value="delete"><input type="hidden" name="id" value="<?= $m['id'] ?>"><button class="delete-link">Delete</button></form></td></tr><?php endforeach; if(!$members): ?><tr><td colspan="6" class="empty">No members found. Add a member above.</td></tr><?php endif; ?></tbody></table></div></section><?php require "includes/footer.php"; ?>